import React, { useState, useEffect } from "react";
import TaskList from './components/TaskList';
import TaskForm from './components/TaskForm';
import api from "./services/api";

interface Task{
    id: number;
    text: string;
    priority: "High" | "Medium" | "Low";
    doneFlag: boolean;
    dueDate?: string;
    creationDate: string;
}

interface TaskFormData{
    text: string;
    priority: "High" | "Medium" | "Low";
    dueDate?: string;
}

const App: React.FC = () => {
    const[tasks, setTasks] = useState<Task[]>([]);

    const fetchTasks = async () => {
        try{
            const response = await api.get<Task[]>("/tasks");
            setTasks(response.data);
        }catch(error){
            console.error("Error getting tasks", error);
        }
    };

    useEffect(() => {
        fetchTasks();
    }, []);

    const addTask = async (newTask: TaskFormData) => {
        try{
            const response = await api.post<Task>("/tasks",{
                ...newTask,
                doneFlag: false,
            });
            setTasks((prevTasks) => [...prevTasks, response.data]);
        }catch(error){
            console.error("Error adding task: ", error);
        }
    };

    const markTaskAsDone = async (id: number) => {
        try{

            const taskToUpdate = tasks.find((task) => task.id === id);
            if(!taskToUpdate) return;

            const isDone = taskToUpdate.doneFlag;

            if(isDone){
                await api.post('/tasks/${id}/undone');
            }else{
                await api.post('/tasks/${id}/done');
            }

            setTasks((prevTasks) =>
                prevTasks.map((task) =>
                    task.id === id ? { ...task, doneFlag: true } : task
                )
            );
        }catch(error){
            console.error("Error marking task as done", error);
        }
    };

    return (
        <div>
            <h1>To-Do App</h1>
            <TaskForm addTask = {addTask} />
            <TaskList tasks = {tasks} markTaskAsDone = {markTaskAsDone} />
        </div>
    );
};

export default App;
